const request = require('request');

const options = {
  method: 'GET',
  url: 'https://api.procore.com/rest/v1.0/bim_file_extractions',
  qs: {
    project_id: 'SOME_INTEGER_VALUE',
    page: 'SOME_INTEGER_VALUE',
    per_page: 'SOME_INTEGER_VALUE',
    'filters[id]': 'SOME_ARRAY_VALUE',
    'filters[status]': 'SOME_STRING_VALUE',
    'filters[extraction_format]': 'SOME_ARRAY_VALUE',
    'filters[bim_file_id]': 'SOME_ARRAY_VALUE',
    'filters[bim_file_upload_id]': 'SOME_ARRAY_VALUE',
    'filters[file_version_id]': 'SOME_ARRAY_VALUE',
    'filters[document_upload_id]': 'SOME_ARRAY_VALUE',
    'filters[document_revision_id]': 'SOME_ARRAY_VALUE'
  }
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/bim_file_extractions?project_id=SOME_INTEGER_VALUE&page=SOME_INTEGER_VALUE&per_page=SOME_INTEGER_VALUE&filters%5Bid%5D=SOME_ARRAY_VALUE&filters%5Bstatus%5D=SOME_STRING_VALUE&filters%5Bextraction_format%5D=SOME_ARRAY_VALUE&filters%5Bbim_file_id%5D=SOME_ARRAY_VALUE&filters%5Bbim_file_upload_id%5D=SOME_ARRAY_VALUE&filters%5Bfile_version_id%5D=SOME_ARRAY_VALUE&filters%5Bdocument_upload_id%5D=SOME_ARRAY_VALUE&filters%5Bdocument_revision_id%5D=SOME_ARRAY_VALUE"),
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

